import React, { useState, useEffect, useContext, useCallback } from 'react';
import { AuthContext } from '../context/AuthContext';
import API from '../utils/api';
import { FiClock, FiDollarSign, FiBookmark } from 'react-icons/fi';
import { Link } from 'react-router-dom';

const Browse = () => {
  const [projects, setProjects] = useState([]);
  const [loading, setLoading] = useState(true);
  const { user } = useContext(AuthContext);

  const fetchProjects = useCallback(async () => {
    try {
      let res;

      if (user && user.userType === 'student') {
        // Try to get matched projects
        try {
          res = await API.get('/match/projects');
        } catch (err) {
          // If profile not found, show all projects
          console.log('No profile found, showing all projects');
          res = await API.get('/project');
        }
      } else {
        // Not logged in OR client -> show all projects
        res = await API.get('/project');
      }

      setProjects(Array.isArray(res.data) ? res.data : []);
      setLoading(false);
    } catch (err) {
      console.error('Fetch projects error:', err);
      setLoading(false);
    }
  }, [user]);

  useEffect(() => {
    fetchProjects();
  }, [fetchProjects]);

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-16 w-16 border-t-4 border-primary"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 py-12">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="mb-8">
          <h1 className="text-4xl font-bold text-gray-800 mb-4">Browse Projects</h1>
          <p className="text-gray-600">
            {user?.userType === 'student'
              ? 'Projects matched to your skills (if profile exists). Otherwise showing all projects.'
              : 'Discover exciting projects for students'}
          </p>
        </div>

        {/* Filters (UI only - not wired) */}
        <div className="bg-white rounded-lg shadow-md p-6 mb-8">
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <input
              type="text"
              placeholder="Search projects..."
              className="px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-primary"
            />
            <select className="px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-primary">
              <option>All Categories</option>
              <option>Web Development</option>
              <option>Mobile Apps</option>
              <option>Design</option>
              <option>Data Science</option>
            </select>
            <select className="px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-primary">
              <option>All Budgets</option>
              <option>$0 - $500</option>
              <option>$500 - $1000</option>
              <option>$1000+</option>
            </select>
            <select className="px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-primary">
              <option>Experience Level</option>
              <option>Beginner</option>
              <option>Intermediate</option>
              <option>Expert</option>
            </select>
          </div>
        </div>

        {/* Project Cards */}
        <div className="space-y-6">
          {projects.length === 0 ? (
            <div className="text-center py-12">
              <p className="text-gray-600 text-lg">No projects found</p>
              {!user && (
                <Link to="/register" className="text-primary hover:underline mt-4 inline-block">
                  Sign up to see matched projects
                </Link>
              )}
            </div>
          ) : (
            projects.map((project) => {
              const requiredSkills = Array.isArray(project.requiredSkills) ? project.requiredSkills : [];

              return (
                <div
                  key={project._id}
                  className="bg-white rounded-lg shadow-md hover:shadow-xl transition p-6"
                >
                  <div className="flex justify-between items-start mb-4">
                    <div className="flex-1">
                      <div className="flex items-center space-x-3 mb-2">
                        <h2 className="text-2xl font-bold text-gray-800">{project.title}</h2>

                        {project.matchScore !== undefined && project.matchScore !== null && (
                          <span className="px-3 py-1 bg-green-100 text-primary rounded-full text-sm font-semibold">
                            {project.matchScore}% Match
                          </span>
                        )}
                      </div>

                      <p className="text-gray-600 mb-4">{project.description}</p>

                      {/* Skills */}
                      <div className="flex flex-wrap gap-2 mb-4">
                        {requiredSkills.map((skill, index) => (
                          <span
                            key={index}
                            className={`px-3 py-1 rounded-full text-sm ${
                              project.matchingSkills?.includes(skill)
                                ? 'bg-primary text-white'
                                : 'bg-gray-200 text-gray-700'
                            }`}
                          >
                            {skill}
                          </span>
                        ))}
                      </div>

                      {/* Meta Info */}
                      <div className="flex items-center space-x-6 text-gray-600">
                        <div className="flex items-center space-x-2">
                          <FiDollarSign />
                          <span>${project.budget}</span>
                        </div>
                        <div className="flex items-center space-x-2">
                          <FiClock />
                          <span>{project.duration}</span>
                        </div>
                        <span className="px-3 py-1 bg-blue-100 text-blue-700 rounded-full text-sm">
                          {project.experienceLevel}
                        </span>
                      </div>
                    </div>

                    <button className="text-gray-400 hover:text-primary" type="button">
                      <FiBookmark size={24} />
                    </button>
                  </div>

                  <div className="flex justify-between items-center pt-4 border-t">
                    <div className="text-sm text-gray-500">
                      Posted by: {project.client?.name || 'Client'}
                    </div>

                    {user?.userType === 'student' ? (
                      <button
                        type="button"
                        className="px-6 py-2 bg-primary text-white rounded-lg hover:bg-secondary transition font-semibold"
                      >
                        Apply Now
                      </button>
                    ) : (
                      <Link
                        to="/register"
                        className="px-6 py-2 bg-primary text-white rounded-lg hover:bg-secondary transition font-semibold"
                      >
                        Sign up to Apply
                      </Link>
                    )}
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>
    </div>
  );
};

export default Browse;
